Read the Main sheet values, group allowance rows by staff number, and transpose the five allowance names into columns H–L. Write the A–G headers and one row per staff member into Output Required, then compute each row total in column M.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

main = vals["Main"]
out = wb["Output Required"]

ALLOWANCES = [
    "Basic",
    "Housing Allowance",
    "Transport Allowances",
    "Other Allowances",
    "Social Allowances",
]

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def to_number(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).strip())
    except Exception:
        return 0.0

# Copy headers A1:G1 from Main to Output Required
for col in range(1, 8):
    out.cell(row=1, column=col).value = clean(main.cell(row=1, column=col).value)

# Add allowance headers in H1:L1
for i, name in enumerate(ALLOWANCES):
    out.cell(row=1, column=8 + i).value = name

# Group Main rows by staff no.
staff_order = []
staff_data = {}

for r in range(2, main.max_row + 1):
    staff_no = clean(main.cell(row=r, column=1).value)
    if staff_no is None:
        continue

    if staff_no not in staff_data:
        staff_order.append(staff_no)
        staff_data[staff_no] = {
            "base": [clean(main.cell(row=r, column=c).value) for c in range(1, 8)],
            "allowances": {name: 0.0 for name in ALLOWANCES},
        }

    desc = clean(main.cell(row=r, column=8).value)
    amount = to_number(main.cell(row=r, column=9).value)

    if desc is not None:
        desc_l = desc.lower()
        for name in ALLOWANCES:
            if name.lower() == desc_l:
                staff_data[staff_no]["allowances"][name] += amount
                break

# Write one row per staff member
for i, staff_no in enumerate(staff_order):
    r = i + 2
    data = staff_data[staff_no]

    for c, v in enumerate(data["base"], start=1):
        out.cell(row=r, column=c).value = v

    total = 0.0
    for j, name in enumerate(ALLOWANCES):
        v = data["allowances"][name]
        out.cell(row=r, column=8 + j).value = v
        total += v

    out.cell(row=r, column=13).value = total

wb.save(OUT)

print("staff rows:", len(staff_order))
for r in range(2, 2 + len(staff_order)):
    print(r, [out.cell(row=r, column=c).value for c in range(1, 14)])
```

